-- REVIEW-ONLY migration package. Do not deploy without production approval.
CREATE TABLE IF NOT EXISTS institutional_institutions (id text PRIMARY KEY, legal_name text NOT NULL, former_names jsonb NOT NULL DEFAULT '[]', regulator_id text, cik text, lei text, country text NOT NULL, institution_type text NOT NULL, filing_status text, active_status text NOT NULL, source_lineage jsonb NOT NULL, UNIQUE (country, regulator_id));
CREATE TABLE IF NOT EXISTS institutional_filings (id text PRIMARY KEY, institution_id text NOT NULL REFERENCES institutional_institutions(id), filing_type text NOT NULL, reporting_period date NOT NULL, filing_date date NOT NULL, amendment_number integer NOT NULL DEFAULT 0, accession_number text NOT NULL, source_url text NOT NULL, source_checksum text, source_lineage jsonb NOT NULL, effective_version boolean NOT NULL DEFAULT true, UNIQUE(institution_id, accession_number));
CREATE TABLE IF NOT EXISTS institutional_holdings (id text PRIMARY KEY, filing_id text NOT NULL REFERENCES institutional_filings(id), institution_id text NOT NULL REFERENCES institutional_institutions(id), stock_id text REFERENCES stocks(id), issuer_name text NOT NULL, ticker text, isin text, cusip text, sedol text, figi text, share_class text, security_type text, put_call text, voting_authority jsonb, quantity numeric, reported_value numeric, currency text, ownership_percentage numeric, source_row_identity text NOT NULL, source_lineage jsonb NOT NULL, mapping_status text NOT NULL, UNIQUE(filing_id, source_row_identity));
CREATE TABLE IF NOT EXISTS institutional_holding_changes (id text PRIMARY KEY, institution_id text NOT NULL, current_filing_id text NOT NULL, prior_filing_id text NOT NULL, stock_id text, share_class text, put_call text, change_type text NOT NULL, quantity_change numeric, reported_value_change numeric, ownership_percentage_change numeric, rank_change integer, price_effect text NOT NULL DEFAULT 'UNKNOWN', formula_version text NOT NULL, calculated_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS institutional_portfolio_analytics (id text PRIMARY KEY, institution_id text NOT NULL, reporting_period date NOT NULL, metric text NOT NULL, value jsonb NOT NULL, input_filings jsonb NOT NULL, calculation_formula text NOT NULL, version text NOT NULL, calculated_at timestamptz NOT NULL, UNIQUE(institution_id, reporting_period, metric, version));
